// ── Body Text — Type Definitions ────────────────────────────────────────────

/** Anchor preset identifiers — replaces the raw 33-landmark picker */
export type AnchorId =
  | 'nose'
  | 'l_shldr'
  | 'r_shldr'
  | 'l_hand'
  | 'r_hand'
  | 'torso'
  | 'l_foot'
  | 'r_foot';

/** An anchor preset describes how to resolve a 2D screen position from pose landmarks */
export type AnchorPreset =
  | { id: AnchorId; label: string; kind: 'single';   index: number;   offsetY: number }
  | { id: AnchorId; label: string; kind: 'midpoint'; indices: [number, number]; offsetY: number };

/** Visual style for a body text label */
export type BodyTextStyle = 'futuristic' | 'pill';

/** A single body-anchored text label */
export interface BodyText {
  id: string;
  text: string;
  anchor: AnchorId;
  poseIndex: number;   // which detected person (0, 1, 2…) — reserved for future multi-person support
  color: string;       // text + accent color
  style: BodyTextStyle;
  fontSize: number;    // px
  offsetX: number;     // px, additive to preset anchor position
  offsetY: number;     // px, additive to preset anchor position
  showConnector?: boolean;  // Futuristic only; default true
  showAnchorDot?: boolean;  // Futuristic only; default true
  // ── Timeline range ────────────────────────────────────────────────────
  startTime: number;   // seconds — text becomes visible at t >= startTime
  endTime: number;     // seconds — text hides at t > endTime
  ease?: boolean;      // fade in at startTime, fade out at endTime
}

/** Smoothed position for rendering (with velocity tracking) */
export interface SmoothedPosition {
  x: number;
  y: number;
  vx: number;
  vy: number;
  visible: boolean;
}

// ── Pre-processed pose track (uploaded video, single-person) ────────────────

/** A single landmark inside a tracked frame */
export interface TrackedLandmark {
  x: number;
  y: number;
  z: number;
  visibility: number;
}

/** One point in time — a single primary pose or null if undetected */
export interface PoseFrame {
  t: number;                            // seconds (video.currentTime)
  landmarks: TrackedLandmark[] | null;  // null = no pose in this frame
}

/** Ordered (ascending t) array of per-frame results for an uploaded video */
export type PoseTrack = PoseFrame[];

/** Simple status emitted during analyzeVideo() — no frame-by-frame progress */
export interface AnalysisProgress {
  status: 'analyzing' | 'done' | 'error';
}

// ── Presence track (multi-person, for timeline visualization) ──────────────

/** A contiguous time range during which a tracked person is visible. */
export interface PresenceSegment {
  start: number;  // seconds
  end: number;    // seconds
}

/** All appearances of a single tracked identity across the video. */
export interface PersonPresence {
  id: number;             // stable identity (0, 1, 2…)
  color: string;          // assigned from PERSON_COLORS palette
  segments: PresenceSegment[];
}

/** Multi-person presence summary derived from the raw analysis. */
export type PresenceTrack = PersonPresence[];

// ── Body Text — Constants ───────────────────────────────────────────────────

import { AnchorPreset, BodyText } from './types';

// ── Anchor Presets ──────────────────────────────────────────────────────────
// Maps each preset to MediaPipe pose landmark indices (0–32) plus a default
// vertical offset so the label sits at a natural distance from the body part.
// MediaPipe Pose landmark indices used here:
//   0  Nose
//   11 L Shoulder     12 R Shoulder
//   19 L Index (hand) 20 R Index (hand)
//   31 L Foot Index   32 R Foot Index

export const ANCHOR_PRESETS: AnchorPreset[] = [
  { id: 'nose',    label: 'Nose',       kind: 'single',   index: 0,           offsetY: -70 },
  { id: 'l_shldr', label: 'L Shoulder', kind: 'single',   index: 11,          offsetY: -30 },
  { id: 'r_shldr', label: 'R Shoulder', kind: 'single',   index: 12,          offsetY: -30 },
  { id: 'l_hand',  label: 'L Hand',     kind: 'single',   index: 19,          offsetY: -20 },
  { id: 'r_hand',  label: 'R Hand',     kind: 'single',   index: 20,          offsetY: -20 },
  { id: 'torso',   label: 'Torso',      kind: 'midpoint', indices: [11, 12],  offsetY: 40  },
  { id: 'l_foot',  label: 'L Foot',     kind: 'single',   index: 31,          offsetY: 30  },
  { id: 'r_foot',  label: 'R Foot',     kind: 'single',   index: 32,          offsetY: 30  },
];

export const ANCHOR_BY_ID: Record<string, AnchorPreset> = Object.fromEntries(
  ANCHOR_PRESETS.map((a) => [a.id, a])
);

// ── Text Colors ─────────────────────────────────────────────────────────────
export const TEXT_COLORS = [
  '#ffffff',
  '#ff6b6b',
  '#ffd93d',
  '#4d96ff',
  '#6bcb77',
];

// ── Default New Body Text ───────────────────────────────────────────────────
export const DEFAULT_BODY_TEXT: Omit<BodyText, 'id'> = {
  text: 'TEXT',
  anchor: 'nose',
  poseIndex: 0,
  color: '#ffffff',
  style: 'futuristic',
  fontSize: 20,
  offsetX: 0,
  offsetY: 0,
  showConnector: true,
  showAnchorDot: true,
  startTime: 0,
  endTime: 0,
  ease: false,
};

// ── Smoothing (internal only, no UI) ────────────────────────────────────────
export const POSITION_LERP     = 0.25;   // 0–1 — lower = smoother but laggier
export const VELOCITY_DAMPING  = 0.6;    // 0–1 — higher = more momentum
export const DEAD_ZONE         = 5;      // pixels — movements below ignored

// ── Timeline ────────────────────────────────────────────────────────────────
export const MIN_TEXT_DURATION = 0.3;   // seconds — minimum length of a text clip
export const DEFAULT_TEXT_DURATION = 3; // seconds — default span for a new text
export const TIMELINE_SNAP     = 0.1;   // seconds — drag snap (Shift to bypass)

// ── Ease ───────────────────────────────────────────────────────────────────
// Per-side fade duration when a text's `ease` flag is on. Clamped to
// clipLen / 2 at draw time so enter/exit never overlap on short clips.
export const EASE_DURATION     = 0.3;   // seconds

// ── Presence strip (multi-person timeline visualization) ────────────────────
// Palette assigned to tracked identities by ID order. Designed for visibility
// on the dark timeline background.
export const PERSON_COLORS = [
  '#5EE6FF', // cyan
  '#FF8AC8', // pink
  '#FFD166', // amber
  '#A8FF60', // lime
  '#C792EA', // violet
  '#FF8E72', // coral
];

// Merge presence gaps shorter than this (avoids visual shimmer from one-frame
// detection drops while a person is clearly still in view).
export const PRESENCE_GAP_MERGE   = 0.2;  // seconds

// Drop presence segments shorter than this (filters one-off blip detections).
export const PRESENCE_MIN_SEGMENT = 0.15; // seconds

// Identity tracking: max normalized distance (shoulder-midpoint) a person can
// move between consecutive sampled frames before we treat them as a new ID.
export const IDENTITY_MAX_JUMP    = 0.18; // 0–1 (normalized to frame size)

// Retire an identity if unseen for this many consecutive frames.
export const IDENTITY_RETIRE_FRAMES = 12;

// ── Body Text — VideoStage (Render Loop) ────────────────────────────────────

import React, { useRef, useEffect, forwardRef, useImperativeHandle, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { visionService, PoseResult } from '../services/visionService';
import { lookupPoseAtTime } from '../services/poseTrack';
import { BodyText, SmoothedPosition, AnchorPreset, PoseTrack } from '../types';
import { ANCHOR_BY_ID, PERSON_COLORS } from '../constants';
import {
  Output, Mp4OutputFormat, BufferTarget,
  QUALITY_HIGH, Input, BlobSource, ALL_FORMATS, Conversion
} from 'mediabunny';

interface VideoStageProps {
  videoUrl: string | null;
  texts: BodyText[];
  onLoadingChange: (loading: boolean) => void;
  onError: (msg: string) => void;
  onPoseUpdate: (result: PoseResult) => void;
  showLandmarks: boolean;
  isPlaying: boolean;
  poseTrack: PoseTrack | null;
  onTimeUpdate?: (current: number, duration: number) => void;
  onVideoReady?: (duration: number) => void;
  onExportProgress?: (progress: number) => void;
}

export interface VideoStageHandle {
  exportVideo: () => Promise<void>;
  seekTo: (time: number) => void;
  play: () => void;
  pause: () => void;
  /** Returns the underlying <video> element (for pre-pass analysis). */
  getVideoElement: () => HTMLVideoElement | null;
}

// ── Anchor resolver ─────────────────────────────────────────────────────────
function resolveAnchor(
  preset: AnchorPreset,
  landmarks: Array<{ x: number; y: number; visibility?: number }>,
  canvasW: number,
  canvasH: number
): { x: number; y: number; visible: boolean } | null {
  if (preset.kind === 'single') {
    const lm = landmarks[preset.index];
    if (!lm) return null;
    return {
      x: lm.x * canvasW,
      y: lm.y * canvasH,
      visible: (lm.visibility ?? 1) >= 0.3,
    };
  }
  const a = landmarks[preset.indices[0]];
  const b = landmarks[preset.indices[1]];
  if (!a || !b) return null;
  const avgVis = ((a.visibility ?? 1) + (b.visibility ?? 1)) / 2;
  return {
    x: ((a.x + b.x) / 2) * canvasW,
    y: ((a.y + b.y) / 2) * canvasH,
    visible: avgVis >= 0.3,
  };
}

function hexToRgba(hex: string, alpha: number): string {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function drawBodyTextDispatch(
  ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D,
  bodyText: BodyText,
  anchorX: number,
  anchorY: number,
  presetOffsetY: number,
  alpha: number = 1,
) {
  const tx = anchorX + bodyText.offsetX;
  const ty = anchorY + presetOffsetY + bodyText.offsetY;
  if (bodyText.style === 'pill') {
    drawBodyTextPill(ctx, bodyText, anchorX, anchorY, tx, ty, alpha);
  } else {
    drawBodyTextFuturistic(ctx, bodyText, anchorX, anchorY, tx, ty, alpha);
  }
}

function drawBodyTextFuturistic(
  ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D,
  bodyText: BodyText,
  anchorX: number,
  anchorY: number,
  tx: number,
  ty: number,
  alpha: number = 1,
) {
  const { text, color, fontSize } = bodyText;
  const displayText = (text || ' ').toUpperCase();

  ctx.save();
  ctx.font = `600 ${fontSize}px 'Jost', 'Futura', 'Inter', system-ui, sans-serif`;
  const textW = ctx.measureText(displayText).width;

  if (bodyText.showConnector !== false) {
    ctx.beginPath();
    ctx.moveTo(anchorX, anchorY);
    ctx.lineTo(tx, ty);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.4 * alpha;
    ctx.stroke();
    ctx.globalAlpha = alpha;
  }

  if (bodyText.showAnchorDot !== false) {
    const dHalf = Math.max(3, fontSize * 0.17);
    ctx.save();
    ctx.translate(anchorX, anchorY);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.7 * alpha;
    ctx.fillRect(-dHalf, -dHalf, dHalf * 2, dHalf * 2);
    ctx.restore();
  }

  ctx.globalAlpha = alpha;
  ctx.shadowColor = 'rgba(0,0,0,0.6)';
  ctx.shadowBlur = 6;
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(displayText, tx, ty);
  ctx.shadowBlur = 0;

  ctx.beginPath();
  ctx.moveTo(tx - textW / 2, ty + fontSize * 0.55);
  ctx.lineTo(tx + textW / 2, ty + fontSize * 0.55);
  ctx.strokeStyle = color;
  ctx.lineWidth = 1.5;
  ctx.globalAlpha = 0.5 * alpha;
  ctx.stroke();
  ctx.restore();
}

function drawBodyTextPill(
  ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D,
  bodyText: BodyText,
  _anchorX: number,
  _anchorY: number,
  tx: number,
  ty: number,
  alpha: number = 1,
) {
  const { text, color, fontSize } = bodyText;
  const displayText = text || ' ';

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = `500 ${fontSize}px 'Inter', system-ui, sans-serif`;
  const textW = ctx.measureText(displayText).width;

  const padX = fontSize * 0.6;
  const padY = fontSize * 0.35;
  const pillW = textW + padX * 2;
  const pillH = fontSize + padY * 2;
  const x = tx - pillW / 2;
  const y = ty - pillH / 2;
  const r = pillH / 2;

  ctx.shadowColor = 'rgba(0,0,0,0.35)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 1;

  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + pillW - r, y);
  ctx.arcTo(x + pillW, y, x + pillW, y + r, r);
  ctx.lineTo(x + pillW, y + pillH - r);
  ctx.arcTo(x + pillW, y + pillH, x + pillW - r, y + pillH, r);
  ctx.lineTo(x + r, y + pillH);
  ctx.arcTo(x, y + pillH, x, y + pillH - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();

  ctx.fillStyle = hexToRgba(color, 0.22);
  ctx.fill();

  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;

  ctx.lineWidth = 1;
  ctx.strokeStyle = hexToRgba(color, 0.5);
  ctx.stroke();

  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(displayText, tx, ty);

  ctx.restore();
}

function applySmoothing(
  map: Map<string, SmoothedPosition>,
  key: string,
  rawX: number,
  rawY: number,
  visible: boolean,
  lerp: number,
  damping: number,
  deadZone: number
): SmoothedPosition {
  const prev = map.get(key);
  if (!prev || !visible) {
    const pos = { x: rawX, y: rawY, vx: 0, vy: 0, visible };
    map.set(key, pos);
    return pos;
  }
  const dx = rawX - prev.x;
  const dy = rawY - prev.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  if (dist < deadZone) {
    const pos = { ...prev, vx: prev.vx * damping * 0.5, vy: prev.vy * damping * 0.5, visible };
    map.set(key, pos);
    return pos;
  }

  const vx = dx * lerp + prev.vx * damping;
  const vy = dy * lerp + prev.vy * damping;
  const pos = { x: prev.x + vx, y: prev.y + vy, vx, vy, visible };
  map.set(key, pos);
  return pos;
}

import { POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE } from '../constants';

export const VideoStage = forwardRef<VideoStageHandle, VideoStageProps>(
  ({
    videoUrl, texts, onLoadingChange, onError, onPoseUpdate,
    showLandmarks, isPlaying, onTimeUpdate, onVideoReady, onExportProgress,
    poseTrack,
  }, ref) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const rafIdRef = useRef<number | undefined>(undefined);
    const rvfcIdRef = useRef<number | undefined>(undefined);

    const smoothedPositions = useRef<Map<string, SmoothedPosition>>(new Map());
    const latestPoseRef = useRef<PoseResult>({ landmarks: [] });

    const textsRef = useRef(texts);
    const showLandmarksRef = useRef(showLandmarks);
    const poseTrackRef = useRef<PoseTrack | null>(poseTrack);

    useEffect(() => { textsRef.current = texts; }, [texts]);
    useEffect(() => { showLandmarksRef.current = showLandmarks; }, [showLandmarks]);
    useEffect(() => { poseTrackRef.current = poseTrack; }, [poseTrack]);

    useEffect(() => {
      if (!poseTrack || poseTrack.length === 0) return;
      onPoseUpdate({ landmarks: [[]] });
    }, [poseTrack, onPoseUpdate]);

    const renderFrame = useCallback(() => {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (!video || !canvas || video.readyState < 2) {
        rafIdRef.current = requestAnimationFrame(renderFrame);
        return;
      }
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
        canvas.width = video.videoWidth || 1280;
        canvas.height = video.videoHeight || 720;
      }

      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      let poses: PoseResult;
      let usingCache = false;
      const cache = poseTrackRef.current;
      if (cache && cache.length > 0) {
        const lms = lookupPoseAtTime(cache, video.currentTime);
        usingCache = true;
        poses = { landmarks: lms ? [lms] : [] };
      } else {
        poses = latestPoseRef.current;
      }

      // Landmark overlay — match colors to the presence bar
      if (showLandmarksRef.current && poses.landmarks.length > 0) {
        ctx.save();
        poses.landmarks.forEach((lms, pIdx) => {
          const personColor = PERSON_COLORS[pIdx % PERSON_COLORS.length];
          for (const lm of lms) {
            if ((lm.visibility ?? 1) < 0.5) continue;
            const px = lm.x * canvas.width;
            const py = lm.y * canvas.height;
            ctx.beginPath();
            ctx.arc(px, py, 3, 0, Math.PI * 2);
            ctx.fillStyle = personColor;
            ctx.globalAlpha = 0.6;
            ctx.fill();
            // Inner core for contrast
            ctx.beginPath();
            ctx.arc(px, py, 1, 0, Math.PI * 2);
            ctx.fillStyle = 'white';
            ctx.globalAlpha = 0.8;
            ctx.fill();
          }
        });
        ctx.restore();
      }

      const currentTexts = textsRef.current;
      const videoTime = video.currentTime;
      for (const t of currentTexts) {
        if (videoTime < t.startTime || videoTime > t.endTime) {
          smoothedPositions.current.delete(t.id);
          continue;
        }
        const preset = ANCHOR_BY_ID[t.anchor];
        if (!preset) continue;
        const poseArrIdx = usingCache ? 0 : t.poseIndex;
        const poseLandmarks = poseArrIdx >= 0 ? poses.landmarks[poseArrIdx] : undefined;
        const key = t.id;

        if (!poseLandmarks) {
          applySmoothing(smoothedPositions.current, key, 0, 0, false,
            POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE);
          continue;
        }

        const anchor = resolveAnchor(preset, poseLandmarks, canvas.width, canvas.height);
        if (!anchor || !anchor.visible) {
          applySmoothing(smoothedPositions.current, key, 0, 0, false,
            POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE);
          continue;
        }

        const smoothed = usingCache
          ? { x: anchor.x, y: anchor.y, vx: 0, vy: 0, visible: true }
          : applySmoothing(
              smoothedPositions.current, key,
              anchor.x, anchor.y, true,
              POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE,
            );

        // Instant visibility
        drawBodyTextDispatch(ctx, t, smoothed.x, smoothed.y, preset.offsetY, 1);
      }

      rafIdRef.current = requestAnimationFrame(renderFrame);
    }, []);

    const runDetection = useCallback(() => {
      const video = videoRef.current;
      if (!video || video.readyState < 2) return;
      if (!visionService.isReady()) return;
      if (poseTrackRef.current && poseTrackRef.current.length > 0) return;
      const hasConsumer = textsRef.current.length > 0 || showLandmarksRef.current;
      if (!hasConsumer) return;
      if (video.paused && latestPoseRef.current.landmarks.length > 0) return;

      const result = visionService.detectPoses(video, performance.now());
      latestPoseRef.current = result;
      onPoseUpdate(result);
    }, [onPoseUpdate]);

    useImperativeHandle(ref, () => ({
      exportVideo: async () => {
        if (!videoUrl) return;

        try {
          onLoadingChange(true);
          const response = await fetch(videoUrl);
          const blob = await response.blob();

          const input = new Input({ source: new BlobSource(blob), formats: ALL_FORMATS });
          const output = new Output({
            format: new Mp4OutputFormat({ fastStart: 'in-memory' }),
            target: new BufferTarget(),
          });

          const exportSmoothed = new Map<string, SmoothedPosition>();
          visionService.resetTimestamp();
          await visionService.prepareForExport();

          const offCanvas = document.createElement('canvas');
          let offCtx: CanvasRenderingContext2D | null = null;

          const exportCache = poseTrackRef.current;
          const useCacheForExport = !!exportCache && exportCache.length > 0;

          const conversion = await Conversion.init({
            input,
            output,
            video: {
              codec: 'avc',
              bitrate: QUALITY_HIGH,
              forceTranscode: true,
              process: (sample) => {
                if (!offCtx) {
                  offCanvas.width = sample.displayWidth;
                  offCanvas.height = sample.displayHeight;
                  offCtx = offCanvas.getContext('2d')!;
                }

                sample.draw(offCtx, 0, 0);

                let poses: PoseResult;
                let usingCacheFrame = false;
                if (useCacheForExport) {
                  const lms = lookupPoseAtTime(exportCache!, sample.timestamp);
                  usingCacheFrame = true;
                  poses = { landmarks: lms ? [lms] : [] };
                } else {
                  poses = visionService.detectInFrame(offCanvas);
                }

                // Landmark dots are explicitly omitted from export rendering here.

                for (const t of textsRef.current) {
                  if (sample.timestamp < t.startTime || sample.timestamp > t.endTime) {
                    exportSmoothed.delete(t.id);
                    continue;
                  }
                  const preset = ANCHOR_BY_ID[t.anchor];
                  if (!preset) continue;
                  const poseArrIdx = usingCacheFrame ? 0 : t.poseIndex;
                  const poseLandmarks = poseArrIdx >= 0 ? poses.landmarks[poseArrIdx] : undefined;
                  const key = t.id;

                  if (!poseLandmarks) {
                    applySmoothing(exportSmoothed, key, 0, 0, false,
                      POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE);
                    continue;
                  }
                  const anchor = resolveAnchor(preset, poseLandmarks, offCanvas.width, offCanvas.height);
                  if (!anchor || !anchor.visible) {
                    applySmoothing(exportSmoothed, key, 0, 0, false,
                      POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE);
                    continue;
                  }
                  const smoothed = usingCacheFrame
                    ? { x: anchor.x, y: anchor.y, vx: 0, vy: 0, visible: true }
                    : applySmoothing(
                        exportSmoothed, key,
                        anchor.x, anchor.y, true,
                        POSITION_LERP, VELOCITY_DAMPING, DEAD_ZONE,
                      );

                  drawBodyTextDispatch(offCtx, t, smoothed.x, smoothed.y, preset.offsetY, 1);
                }

                return offCanvas;
              }
            }
          });

          if (!conversion.isValid) throw new Error('Export initialization failed');
          conversion.onProgress = (p) => { if (onExportProgress) onExportProgress(p); };

          await conversion.execute();

          const resultBuffer = output.target.buffer!;
          const u8 = new Uint8Array(resultBuffer);
          let binary = '';
          const CHUNK = 0x8000;
          for (let i = 0; i < u8.length; i += CHUNK) {
            binary += String.fromCharCode.apply(null, Array.from(u8.subarray(i, i + CHUNK)) as any);
          }
          const base64 = btoa(binary);
          await Flow.save({
            base64,
            mimeType: 'video/mp4',
            name: `body-text-${Date.now()}`,
          });
        } catch (err) {
          onError(err instanceof Error ? err.message : 'Export failed');
        } finally {
          await visionService.restoreAfterExport();
          onLoadingChange(false);
          if (onExportProgress) onExportProgress(0);
        }
      },
      seekTo: (time: number) => {
        if (videoRef.current) videoRef.current.currentTime = time;
      },
      play: () => { videoRef.current?.play(); },
      pause: () => { videoRef.current?.pause(); },
      getVideoElement: () => videoRef.current,
    }));

    const drawSingleFrame = useCallback(() => {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (!video || !canvas || video.readyState < 2) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
        canvas.width = video.videoWidth || 1280;
        canvas.height = video.videoHeight || 720;
      }
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    }, []);

    useEffect(() => {
      let isActive = true;
      async function setup() {
        try {
          onLoadingChange(true);
          await visionService.initialize();
          visionService.resetTimestamp();
          smoothedPositions.current.clear();
          latestPoseRef.current = { landmarks: [] };
          onPoseUpdate({ landmarks: [] });

          const video = videoRef.current;
          if (!video) return;

          video.onloadedmetadata = null;
          video.ontimeupdate = null;
          video.onseeked = null;
          video.removeAttribute('src');
          video.load();

          if (!isActive) return;

          if (videoUrl) {
            const handleMetadata = () => {
              video.currentTime = 0;
              video.pause();
              if (onVideoReady) onVideoReady(video.duration);
              onLoadingChange(false);
            };
            video.onloadedmetadata = handleMetadata;
            video.onseeked = () => {
              latestPoseRef.current = { landmarks: [] };
              drawSingleFrame();
              runDetection();
            };
            video.ontimeupdate = () => {
              if (onTimeUpdate) onTimeUpdate(video.currentTime, video.duration);
            };
            video.muted = false;
            video.playsInline = true;
            video.preload = 'auto';
            video.src = videoUrl;

            if (video.readyState >= 1) {
              queueMicrotask(() => {
                if (!isActive) return;
                if (video.readyState >= 1) handleMetadata();
              });
            }
          } else {
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext('2d');
            if (canvas && ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
            onLoadingChange(false);
          }
        } catch (err) {
          onError(err instanceof Error ? err.message : 'Failed to start video source');
          onLoadingChange(false);
        }
      }
      setup();
      return () => { isActive = false; };
    }, [videoUrl]);

    useEffect(() => {
      rafIdRef.current = requestAnimationFrame(renderFrame);
      return () => { if (rafIdRef.current !== undefined) cancelAnimationFrame(rafIdRef.current); };
    }, [renderFrame]);

    useEffect(() => {
      const video = videoRef.current;
      if (!video) return;
      let cancelled = false;
      if ('requestVideoFrameCallback' in HTMLVideoElement.prototype) {
        const tick = () => {
          if (cancelled) return;
          runDetection();
          rvfcIdRef.current = (video as any).requestVideoFrameCallback(tick);
        };
        rvfcIdRef.current = (video as any).requestVideoFrameCallback(tick);
        return () => {
          cancelled = true;
          if (rvfcIdRef.current !== undefined && 'cancelVideoFrameCallback' in video) {
            (video as any).cancelVideoFrameCallback(rvfcIdRef.current);
          }
        };
      }
      let handle: number | undefined;
      const loop = () => {
        if (cancelled) return;
        runDetection();
        handle = requestAnimationFrame(loop);
      };
      handle = requestAnimationFrame(loop);
      return () => { cancelled = true; if (handle !== undefined) cancelAnimationFrame(handle); };
    }, [runDetection]);

    useEffect(() => {
      if (!videoRef.current) return;
      if (isPlaying) videoRef.current.play().catch(() => {});
      else videoRef.current.pause();
    }, [isPlaying]);

    return (
      <div className="absolute inset-0 w-full h-full bg-zinc-950 flex items-center justify-center">
        <video ref={videoRef} className="absolute inset-0 w-full h-full object-contain opacity-0 pointer-events-none" playsInline />
        <canvas ref={canvasRef} className="w-full h-full object-contain" />
      </div>
    );
  }
);

// ── Body Text — Presence Strip ──────────────────────────────────────────────
//
// Shows WHEN each detected person appears in the video, as colored ribbons
// stacked above the clip lane on the Timeline.
//
// Alignment & Overflow Fix:
//   • Mirrored the exact layout structure of the Timeline control row.
//   • Clamped 'left' and 'width' percentages to ensure ribbons never exceed 
//     the 100% track boundary even with timing jitter.

import React, { useCallback, useMemo, useRef, useState } from 'react';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { PresenceTrack } from '../types';
import { presenceAtTime } from '../services/poseTrack';

interface PresenceStripProps {
  presence: PresenceTrack;
  duration: number;
}

const ROW_H = 6;          // px — height of each presence row
const ROW_GAP = 2;        // px — gap between rows in expanded mode
const COLLAPSED_PAD = 1;  // px — vertical breathing room around the single row

function formatTime(s: number): string {
  if (!isFinite(s) || s < 0) s = 0;
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

export const PresenceStrip: React.FC<PresenceStripProps> = ({ presence, duration }) => {
  const [expanded, setExpanded] = useState(false);
  const [tooltip, setTooltip] = useState<{
    x: number;       // px relative to strip container
    t: number;       // seconds
    ids: number[];
  } | null>(null);

  const stripRef = useRef<HTMLDivElement>(null);

  if (presence.length === 0 || duration <= 0) return null;

  const rowsHeight = expanded
    ? presence.length * ROW_H + Math.max(0, presence.length - 1) * ROW_GAP
    : ROW_H + COLLAPSED_PAD * 2;

  const handleMove = useCallback((e: React.MouseEvent) => {
    const el = stripRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const xLocal = e.clientX - rect.left;
    const pct = Math.max(0, Math.min(1, xLocal / rect.width));
    const t = pct * duration;
    setTooltip({ x: xLocal, t, ids: presenceAtTime(presence, t) });
  }, [duration, presence]);

  const handleLeave = useCallback(() => setTooltip(null), []);

  const colorById = useMemo(() => {
    const m = new Map<number, string>();
    for (const p of presence) m.set(p.id, p.color);
    return m;
  }, [presence]);

  return (
    <div className="w-full flex items-center gap-4 select-none" style={{ height: rowsHeight + 4 }}>
      {/* 
        Left Mirror: Toggle Button 
        Matches the Play button width (w-8)
      */}
      <div className="w-8 shrink-0 flex items-center justify-center">
        <button
          onClick={() => setExpanded((v) => !v)}
          className="flex items-center justify-center w-6 h-6 rounded-lg hover:bg-white/10 transition-colors cursor-pointer text-white/30 hover:text-white/80"
          title={expanded ? 'Collapse presence' : 'Expand presence'}
        >
          {expanded ? (
            <ChevronDown size={14} strokeWidth={2.5} />
          ) : (
            <ChevronRight size={14} strokeWidth={2.5} />
          )}
        </button>
      </div>

      {/* 
        Middle Mirror: Time Display Spacer
        Matches the Time display width (min-w-[84px])
      */}
      <div className="min-w-[84px] shrink-0" />

      {/* 
        Right Mirror: The Track Lane
        Uses flex-1 to fill the exact same space as the progress bar track.
      */}
      <div className="flex-1 h-full relative">
        <div
          ref={stripRef}
          onMouseMove={handleMove}
          onMouseLeave={handleLeave}
          className="absolute inset-0 rounded-lg bg-black/40 border border-white/5 overflow-visible shadow-inner"
        >
          <div className="absolute left-0 right-0 top-0 bottom-0" style={{ padding: '2px 0' }}>
            {expanded ? (
              presence.map((p, idx) => (
                <div
                  key={p.id}
                  className="absolute left-0 right-0"
                  style={{ 
                    top: idx * (ROW_H + ROW_GAP), 
                    height: ROW_H,
                    padding: '0 4px' // Slight inner padding so ribbons don't touch edges
                  }}
                >
                  {p.segments.map((s, si) => {
                    const start = Math.max(0, s.start);
                    const end = Math.min(duration, s.end);
                    const left = (start / duration) * 100;
                    const width = ((end - start) / duration) * 100;

                    return (
                      <div
                        key={si}
                        className="absolute top-0 bottom-0 rounded-full"
                        style={{
                          left: `${left}%`,
                          width: `${width}%`,
                          background: p.color,
                          opacity: 0.85,
                        }}
                      />
                    );
                  })}
                </div>
              ))
            ) : (
              <div 
                className="absolute left-0 right-0" 
                style={{ 
                  top: COLLAPSED_PAD, 
                  height: ROW_H,
                  padding: '0 4px' 
                }}
              >
                {presence.map((p) =>
                  p.segments.map((s, si) => {
                    const start = Math.max(0, s.start);
                    const end = Math.min(duration, s.end);
                    const left = (start / duration) * 100;
                    const width = ((end - start) / duration) * 100;

                    return (
                      <div
                        key={`${p.id}-${si}`}
                        className="absolute top-0 bottom-0 rounded-full"
                        style={{
                          left: `${left}%`,
                          width: `${width}%`,
                          background: p.color,
                          opacity: 0.7,
                          mixBlendMode: 'screen',
                        }}
                      />
                    );
                  }),
                )}
              </div>
            )}
          </div>

          {tooltip && (
            <div
              className="absolute z-40 pointer-events-none px-2 py-1.5 rounded-xl border border-white/10 flex items-center gap-2 shadow-2xl"
              style={{
                left: tooltip.x,
                bottom: 'calc(100% + 12px)',
                transform: 'translateX(-50%)',
                background: 'rgba(20,20,20,0.98)',
                backdropFilter: 'blur(24px)',
              }}
            >
              <span className="font-mono text-[10px] font-bold text-white/80 tabular-nums">
                {formatTime(tooltip.t)}
              </span>
              <span className="text-white/10 text-[10px]">|</span>
              <div className="flex items-center gap-2">
                {tooltip.ids.length === 0 ? (
                  <span className="text-[10px] font-medium text-white/30 italic">No Detection</span>
                ) : (
                  tooltip.ids.map((id) => (
                    <div key={id} className="flex items-center gap-1.5">
                      <div
                        className="w-2.5 h-2.5 rounded-full ring-1 ring-white/20"
                        style={{ background: colorById.get(id) ?? '#fff' }}
                      />
                      <span className="text-[10px] font-bold text-white/90">P{id + 1}</span>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

