                  {TEXT_COLORS.map((c) => (
                    <button
                      key={c}
                      onClick={() => onUpdateText({ ...editing, color: c })}
                      className={`w-6 h-6 rounded-full border-2 transition-all cursor-pointer ${
                        editing.color === c ? 'border-white scale-110' : 'border-transparent hover:scale-105'
                      }`}
                      style={{ backgroundColor: c }}
                      aria-label={c}
                    />
                  ))}
                </div>
              </div>

              <button
                onClick={() => onDeleteText(editing.id)}
                className="flex items-center justify-center w-full h-[34px] rounded-xl border border-red-500/30 text-red-400 hover:bg-red-500/10 text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer select-none mt-1"
              >
                Delete
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Bottom Actions */}
      <div className="flex flex-col gap-[5px] items-start w-full pt-3 mt-2 border-t border-[rgba(218,220,224,0.15)]">
        <button
          type="button"
          onClick={onExport}
          className="flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer select-none pl-[8px] pr-[16px]"
        >
          <span className="flex items-center justify-center w-6 h-6"><Download size={18} strokeWidth={1.5} /></span>
          <span>Export Video</span>
        </button>
      </div>
    </div>
  );
};

const DragNumberFieldInline: React.FC<{
  label: string;
  value: number;
  min?: number;
  max?: number;
  step?: number;
  suffix?: string;
  onChange: (val: number) => void;
}> = ({ label, value, min = -999, max = 999, step = 1, suffix = 'px', onChange }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) {
      onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    }
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };

    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };

    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div
      onMouseDown={handleMouseDown}
      className={`flex-1 border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${
        isEditing ? '' : 'cursor-ns-resize'
      }`}
    >
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') commitEdit(editValue);
              if (e.key === 'Escape') setIsEditing(false);
            }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0"
            autoFocus
          />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">
              {value}{suffix}
            </span>
            <div className="flex flex-col items-center mr-1.5 text-white/30">
              <svg width="8" height="5" viewBox="0 0 10 6" fill="none"><path d="M5 0L9 5H1L5 0Z" fill="currentColor"/></svg>
              <svg width="8" height="5" viewBox="0 0 10 6" fill="none"><path d="M5 6L1 1H9L5 6Z" fill="currentColor"/></svg>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

