// ── Body Text — Timeline ────────────────────────────────────────────────────
//
// Full-width bottom bar: play/pause + current/total time + track with
// draggable clip blocks and a playhead.
//
// Refined for high-fidelity control:
//   • Track height of 52px for easy target acquisition.
//   • Enhanced text block handles with vertical indicators.
//   • Instant positional updates (no transition-all on blocks) for zero-lag dragging.

import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import { Play, Pause } from 'lucide-react';
import { BodyText, PresenceTrack } from '../types';
import { MIN_TEXT_DURATION, TIMELINE_SNAP } from '../constants';
import { PresenceStrip } from './PresenceStrip';

interface TimelineProps {
  texts: BodyText[];
  currentTime: number;
  duration: number;
  isPlaying: boolean;
  selectedTextId: string | null;
  presence: PresenceTrack | null;
  onTogglePlay: () => void;
  onSeek: (time: number) => void;
  onSelectText: (id: string | null) => void;
  onUpdateTexts: (next: BodyText[]) => void;
}

function formatTime(s: number): string {
  if (!isFinite(s) || s < 0) s = 0;
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

type DragMode = 'move' | 'resize-start' | 'resize-end';

export const Timeline: React.FC<TimelineProps> = ({
  texts, currentTime, duration, isPlaying, selectedTextId, presence,
  onTogglePlay, onSeek, onSelectText, onUpdateTexts,
}) => {
  const trackRef = useRef<HTMLDivElement>(null);
  const playheadRef = useRef<HTMLDivElement>(null);

  const textsRef = useRef(texts);
  useEffect(() => { textsRef.current = texts; }, [texts]);

  useEffect(() => {
    const el = playheadRef.current;
    if (!el || !isFinite(duration) || duration <= 0) return;
    const pct = Math.max(0, Math.min(1, currentTime / duration)) * 100;
    el.style.left = `${pct}%`;
  }, [currentTime, duration]);

  const timeFromClientX = useCallback((clientX: number): number => {
    const track = trackRef.current;
    if (!track || duration <= 0) return 0;
    const rect = track.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    return pct * duration;
  }, [duration]);

  const handleClipLaneMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0) return;
    const t = timeFromClientX(e.clientX);
    onSeek(t);
    onSelectText(null);
  }, [timeFromClientX, onSeek, onSelectText]);

  const startScrub = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    e.preventDefault();
    if (duration <= 0) return;

    onSelectText(null);
    onSeek(timeFromClientX(e.clientX));

    const onMove = (ev: MouseEvent) => {
      onSeek(timeFromClientX(ev.clientX));
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.body.style.cursor = '';
    };
    document.body.style.cursor = 'grabbing';
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }, [duration, onSeek, onSelectText, timeFromClientX]);

  const startDrag = useCallback((
    e: React.MouseEvent,
    textId: string,
    mode: DragMode,
  ) => {
    e.stopPropagation();
    e.preventDefault();

    const track = trackRef.current;
    if (!track || duration <= 0) return;

    const initial = textsRef.current.find((t) => t.id === textId);
    if (!initial) return;

    onSelectText(textId);

    const startX = e.clientX;
    const startA = initial.startTime;
    const startB = initial.endTime;
    const rect = track.getBoundingClientRect();
    const pxPerSec = rect.width / duration;

    const snap = (v: number, bypass: boolean) =>
      bypass ? v : Math.round(v / TIMELINE_SNAP) * TIMELINE_SNAP;

    const onMove = (ev: MouseEvent) => {
      const dt = (ev.clientX - startX) / pxPerSec;
      const bypass = ev.shiftKey;
      let nextStart = startA;
      let nextEnd = startB;

      if (mode === 'move') {
        const len = startB - startA;
        let s = snap(startA + dt, bypass);
        s = Math.max(0, Math.min(duration - len, s));
        nextStart = s;
        nextEnd = s + len;
      } else if (mode === 'resize-start') {
        let s = snap(startA + dt, bypass);
        s = Math.max(0, Math.min(s, startB - MIN_TEXT_DURATION));
        nextStart = s;
      } else {
        let e2 = snap(startB + dt, bypass);
        e2 = Math.min(duration, Math.max(e2, startA + MIN_TEXT_DURATION));
        nextEnd = e2;
      }

      onUpdateTexts(
        textsRef.current.map((t) =>
          t.id === textId ? { ...t, startTime: nextStart, endTime: nextEnd } : t,
        ),
      );
    };

    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.body.style.cursor = '';
    };

    document.body.style.cursor = mode === 'move' ? 'grabbing' : 'ew-resize';
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }, [duration, onSelectText, onUpdateTexts]);

  const blocks = useMemo(() => {
    if (duration <= 0) return null;
    return texts.map((t) => {
      const leftPct = Math.max(0, Math.min(1, t.startTime / duration)) * 100;
      const rawWidthPct = Math.max(0, (t.endTime - t.startTime) / duration) * 100;
      const widthStyle = `max(12px, ${rawWidthPct}%)`;
      const selected = selectedTextId === t.id;
      return (
        <div
          key={t.id}
          onMouseDown={(e) => startDrag(e, t.id, 'move')}
          onClick={(e) => e.stopPropagation()}
          className={`absolute top-1 bottom-1 rounded-md flex items-center px-1 overflow-hidden select-none transition-colors duration-150 ${
            selected
              ? 'bg-[#969696] text-black z-20 ring-1 ring-white/50 shadow-lg'
              : 'bg-white/10 text-white/90 hover:bg-white/20 z-10'
          }`}
          style={{
            left: `${leftPct}%`,
            width: widthStyle,
            cursor: 'grab',
          }}
          title={`${t.text || 'Untitled'} · ${formatTime(t.startTime)} → ${formatTime(t.endTime)}`}
        >
          {/* Resize start handle */}
          <div
            onMouseDown={(e) => startDrag(e, t.id, 'resize-start')}
            className={`absolute left-0 top-0 bottom-0 w-3 cursor-ew-resize flex items-center justify-center group transition-colors ${
              selected ? 'hover:bg-black/10' : 'hover:bg-white/20'
            }`}
          >
            <div className={`w-[2px] h-3 rounded-full ${selected ? 'bg-black/20' : 'bg-white/20'}`} />
          </div>

          <span className="text-[10px] font-bold tracking-[0.1px] truncate px-3 flex-1 text-center pointer-events-none">
            {t.text || 'Untitled'}
          </span>

          {/* Resize end handle */}
          <div
            onMouseDown={(e) => startDrag(e, t.id, 'resize-end')}
            className={`absolute right-0 top-0 bottom-0 w-3 cursor-ew-resize flex items-center justify-center group transition-colors ${
              selected ? 'hover:bg-black/10' : 'hover:bg-white/20'
            }`}
          >
            <div className={`w-[2px] h-3 rounded-full ${selected ? 'bg-black/20' : 'bg-white/20'}`} />
          </div>
        </div>
      );
    });
  }, [texts, duration, selectedTextId, startDrag]);

  return (
    <div
      className="absolute bottom-4 left-4 right-4 flex flex-col gap-2 px-4 py-3 border border-[rgba(218,220,224,0.15)] rounded-2xl z-20"
      style={{ background: 'rgba(26,26,26,0.85)', backdropFilter: 'blur(24px)' }}
    >
      {presence && presence.length > 0 && (
        <PresenceStrip presence={presence} duration={duration} />
      )}

      <div className="flex items-center gap-4">
        {/* Play / Pause */}
        <button
          onClick={onTogglePlay}
          className="w-8 h-8 flex items-center justify-center hover:bg-white/10 rounded-xl transition-all active:scale-95 cursor-pointer shrink-0"
        >
          {isPlaying ? (
            <Pause size={18} strokeWidth={2} className="text-white" />
          ) : (
            <Play size={18} strokeWidth={2} className="text-white ml-0.5" />
          )}
        </button>

        {/* Time Display */}
        <div className="flex items-center gap-1.5 text-[11px] font-bold text-[#c7c9cd] tracking-[0.2px] font-mono select-none shrink-0 min-w-[84px]">
          <span className="text-white">{formatTime(currentTime)}</span>
          <span className="opacity-20">/</span>
          <span className="opacity-60">{formatTime(duration)}</span>
        </div>

        {/* Track — stretching flush to right padding */}
        <div
          ref={trackRef}
          className="relative flex-1 h-[52px] rounded-xl bg-black/50 border border-white/5 overflow-hidden shadow-inner"
        >
          {/* Scrubber rail */}
          <div
            onMouseDown={startScrub}
            className="absolute top-0 left-0 right-0 h-4 bg-white/5 border-b border-white/5 cursor-pointer z-20"
          />

          {/* Clip lane */}
          <div
            onMouseDown={handleClipLaneMouseDown}
            className="absolute top-4 left-0 right-0 bottom-0 cursor-pointer"
          >
            {blocks}
          </div>

          {/* Playhead */}
          <div
            ref={playheadRef}
            className="absolute top-0 bottom-0 pointer-events-none z-30"
            style={{ left: '0%' }}
          >
            <div className="absolute top-4 bottom-0 left-0 w-[1px] -translate-x-1/2 bg-white/80" />
            <div
              onMouseDown={startScrub}
              className="absolute top-[3px] left-0 w-2.5 h-2.5 -translate-x-1/2 rounded-full bg-white pointer-events-auto cursor-grab z-40 shadow-lg ring-1 ring-black/20"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

// ── Pose Track — Offline post-processing pipeline (single-person) ───────────
//
// Takes raw per-frame MediaPipe output from an uploaded video and produces a
// clean, gap-filled, bidirectionally-smoothed PoseTrack for the renderer to
// consume. Tracks only ONE person — when multiple are detected in a frame,
// picks the pose with the highest mean landmark visibility.
//
// Pipeline: selectPrimary → outlierReject → fillGaps → smoothBidirectional
//
// All functions are pure (no DOM, no side effects) so they're safe to run on
// any thread or snapshot for testing.

import {
  PersonPresence,
  PoseFrame,
  PoseTrack,
  PresenceSegment,
  PresenceTrack,
  TrackedLandmark,
} from '../types';
import {
  IDENTITY_MAX_JUMP,
  IDENTITY_RETIRE_FRAMES,
  PERSON_COLORS,
  PRESENCE_GAP_MERGE,
  PRESENCE_MIN_SEGMENT,
} from '../constants';

// ── Raw input shape (what visionService detect returns per frame) ───────────
export interface RawDetectedPose {
  landmarks: TrackedLandmark[];
}
export interface RawFrame {
  t: number;
  poses: RawDetectedPose[];
}

// ── Tunables ────────────────────────────────────────────────────────────────
const GAP_FILL_MAX = 10;   // interpolate gaps up to this many frames
const SMOOTH_WINDOW = 5;   // centered moving-average window
const OUTLIER_FACTOR = 3;  // velocity spike threshold multiplier

// ── Primary-person selection ────────────────────────────────────────────────
// Picks the pose whose landmarks have the highest mean visibility.
export function selectPrimaryPose(poses: RawDetectedPose[]): RawDetectedPose | null {
  if (poses.length === 0) return null;
  if (poses.length === 1) return poses[0];
  let best = poses[0];
  let bestScore = meanVisibility(best.landmarks);
  for (let i = 1; i < poses.length; i++) {
    const s = meanVisibility(poses[i].landmarks);
    if (s > bestScore) {
      bestScore = s;
      best = poses[i];
    }
  }
  return best;
}

function meanVisibility(lms: TrackedLandmark[]): number {
  if (lms.length === 0) return 0;
  let sum = 0;
  for (const l of lms) sum += l.visibility;
  return sum / lms.length;
}

// ── Build single-person frames from raw input ──────────────────────────────
export function buildFrames(raw: RawFrame[]): PoseFrame[] {
  return raw.map((f) => {
    const primary = selectPrimaryPose(f.poses);
    return {
      t: f.t,
      landmarks: primary ? primary.landmarks : null,
    };
  });
}

// ── Outlier rejection ───────────────────────────────────────────────────────
// Single-frame position spikes (where a landmark jumps out and back) are
// replaced by the midpoint of their neighbors. Only operates on runs of three
// consecutive frames that all have a detected pose.
export function outlierReject(frames: PoseFrame[]): PoseFrame[] {
  if (frames.length < 3) return frames;
  for (let i = 1; i < frames.length - 1; i++) {
    const prev = frames[i - 1].landmarks;
    const cur = frames[i].landmarks;
    const next = frames[i + 1].landmarks;
    if (!prev || !cur || !next) continue;
    for (let li = 0; li < cur.length; li++) {
      const a = prev[li];
      const c = cur[li];
      const n = next[li];
      if (!a || !c || !n) continue;
      const dAC = Math.hypot(c.x - a.x, c.y - a.y);
      const dCN = Math.hypot(n.x - c.x, n.y - c.y);
      const dAN = Math.hypot(n.x - a.x, n.y - a.y);
      // spike = out+back >> direct
      if (dAC + dCN > OUTLIER_FACTOR * dAN + 0.02) {
        c.x = (a.x + n.x) / 2;
        c.y = (a.y + n.y) / 2;
        c.z = (a.z + n.z) / 2;
        c.visibility = Math.min(a.visibility, n.visibility);
      }
    }
  }
  return frames;
}

// ── Gap filling ─────────────────────────────────────────────────────────────
// Find runs of null frames bounded by detected ones. If gap <= GAP_FILL_MAX,
// linearly interpolate every landmark and fill in synthetic poses.
export function fillGaps(frames: PoseFrame[]): PoseFrame[] {
  if (frames.length === 0) return frames;

  // Collect indices where we have a pose
  const detected: number[] = [];
  for (let i = 0; i < frames.length; i++) {
    if (frames[i].landmarks) detected.push(i);
  }

  for (let k = 1; k < detected.length; k++) {
    const prevFi = detected[k - 1];
    const nextFi = detected[k];
    const gap = nextFi - prevFi - 1;
    if (gap <= 0 || gap > GAP_FILL_MAX) continue;

    const prevLms = frames[prevFi].landmarks!;
    const nextLms = frames[nextFi].landmarks!;

    for (let g = 1; g <= gap; g++) {
      const fi = prevFi + g;
      const alpha = g / (gap + 1);
      const newLandmarks: TrackedLandmark[] = prevLms.map((a, li) => {
        const b = nextLms[li] ?? a;
        return {
          x: a.x + (b.x - a.x) * alpha,
          y: a.y + (b.y - a.y) * alpha,
          z: a.z + (b.z - a.z) * alpha,
          visibility: Math.min(a.visibility, b.visibility),
        };
      });
      frames[fi].landmarks = newLandmarks;
    }
  }

  return frames;
}

// ── Bidirectional smoothing ────────────────────────────────────────────────
// Centered moving-average (window SMOOTH_WINDOW, default 5) applied per
// (landmarkIndex, channel) across runs of contiguous non-null frames.
export function smoothBidirectional(frames: PoseFrame[]): PoseFrame[] {
  if (frames.length < 3) return frames;
  const half = Math.floor(SMOOTH_WINDOW / 2);

  // Walk runs of contiguous non-null frames
  let runStart = -1;
  for (let i = 0; i <= frames.length; i++) {
    const has = i < frames.length && frames[i].landmarks !== null;
    if (has && runStart < 0) {
      runStart = i;
    } else if (!has && runStart >= 0) {
      const runLen = i - runStart;
      if (runLen >= 3) smoothRun(frames, runStart, i - 1, half);
      runStart = -1;
    }
  }

  return frames;
}

function smoothRun(frames: PoseFrame[], lo: number, hi: number, half: number) {
  const L = frames[lo].landmarks!.length;
  const runLen = hi - lo + 1;
  // Snapshot originals so the moving average doesn't feed on its own output
  const orig: TrackedLandmark[][] = [];
  for (let i = 0; i < runLen; i++) {
    orig.push(frames[lo + i].landmarks!.map((lm) => ({ ...lm })));
  }

  for (let i = 0; i < runLen; i++) {
    const lo2 = Math.max(0, i - half);
    const hi2 = Math.min(runLen - 1, i + half);
    const target = frames[lo + i].landmarks!;
    for (let li = 0; li < L; li++) {
      let sx = 0, sy = 0, sz = 0, sv = 0, n = 0;
      for (let j = lo2; j <= hi2; j++) {
        const l = orig[j][li];
        sx += l.x; sy += l.y; sz += l.z; sv += l.visibility;
        n++;
      }
      target[li].x = sx / n;
      target[li].y = sy / n;
      target[li].z = sz / n;
      target[li].visibility = sv / n;
    }
  }
}

// ── Lookup helper ──────────────────────────────────────────────────────────
// Binary-search nearest frame by timestamp. Returns that frame's landmarks
// (or null if the nearest frame had no detection).
export function lookupPoseAtTime(track: PoseTrack, t: number): TrackedLandmark[] | null {
  if (track.length === 0) return null;
  let lo = 0, hi = track.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (track[mid].t < t) lo = mid + 1;
    else hi = mid;
  }
  let cand = track[lo];
  if (lo > 0) {
    const prev = track[lo - 1];
    if (Math.abs(prev.t - t) < Math.abs(cand.t - t)) cand = prev;
  }
  return cand.landmarks;
}

// ── Identity tracking + presence derivation (multi-person) ─────────────────
//
// The single-person `PoseTrack` above feeds the renderer (which only draws
// one person's anchors). The presence track below is purely informational —
// it summarizes WHEN each detected person is on-screen so the timeline can
// show colored ribbons.
//
// Pipeline: shoulder-midpoint centroid → greedy nearest-neighbor matching
// across consecutive frames → emit segments per ID → merge tiny gaps → drop
// blip segments → assign palette colors.

interface Centroid {
  x: number;
  y: number;
}

/** Returns shoulder-midpoint (x, y) in normalized coords, or null. */
function poseCentroid(landmarks: TrackedLandmark[]): Centroid | null {
  const ls = landmarks[11];
  const rs = landmarks[12];
  if (!ls || !rs) return null;
  // Require some visibility on at least one shoulder so we don't track ghosts.
  if ((ls.visibility ?? 1) < 0.2 && (rs.visibility ?? 1) < 0.2) return null;
  return { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 };
}

interface ActiveId {
  id: number;
  centroid: Centroid;
  lastSeenIdx: number;
}

/**
 * Walks the raw frames, assigns a stable identity to each detected pose, and
 * returns a per-frame map of `id → centroid`. Greedy matching: for each
 * frame, every active ID claims the nearest unmatched detection within
 * IDENTITY_MAX_JUMP. Unmatched detections become new IDs.
 */
function trackIdentities(
  raw: RawFrame[],
): Array<Map<number, Centroid>> {
  const perFrame: Array<Map<number, Centroid>> = [];
  const active: ActiveId[] = [];
  let nextId = 0;

  for (let fi = 0; fi < raw.length; fi++) {
    const frame = raw[fi];

    // Compute centroids for every detected pose this frame.
    const detections: Centroid[] = [];
    for (const p of frame.poses) {
      const c = poseCentroid(p.landmarks);
      if (c) detections.push(c);
    }

    const claimed = new Set<number>(); // detection indices already taken
    const frameMap = new Map<number, Centroid>();

    // Retire IDs that have been gone too long.
    for (let i = active.length - 1; i >= 0; i--) {
      if (fi - active[i].lastSeenIdx > IDENTITY_RETIRE_FRAMES) {
        active.splice(i, 1);
      }
    }

    // For each active ID, find the nearest unclaimed detection within range.
    for (const a of active) {
      let bestIdx = -1;
      let bestDist = IDENTITY_MAX_JUMP;
      for (let di = 0; di < detections.length; di++) {
        if (claimed.has(di)) continue;
        const d = detections[di];
        const dist = Math.hypot(d.x - a.centroid.x, d.y - a.centroid.y);
        if (dist < bestDist) {
          bestDist = dist;
          bestIdx = di;
        }
      }
      if (bestIdx >= 0) {
        claimed.add(bestIdx);
        a.centroid = detections[bestIdx];
        a.lastSeenIdx = fi;
        frameMap.set(a.id, a.centroid);
      }
    }

    // Anything still unclaimed is a new identity.
    for (let di = 0; di < detections.length; di++) {
      if (claimed.has(di)) continue;
      const id = nextId++;
      active.push({ id, centroid: detections[di], lastSeenIdx: fi });
      frameMap.set(id, detections[di]);
    }

    perFrame.push(frameMap);
  }

  return perFrame;
}

/** Merge contiguous timestamps for each ID into segments, then post-process. */
function buildSegments(
  raw: RawFrame[],
  perFrame: Array<Map<number, Centroid>>,
): Map<number, PresenceSegment[]> {
  const open = new Map<number, { start: number; lastT: number }>();
  const out = new Map<number, PresenceSegment[]>();

  // Estimate a per-frame duration so a single isolated detection still gets
  // a non-zero segment length. Falls back to 1/30s if unavailable.
  const dt = raw.length >= 2 ? Math.max(1 / 60, raw[1].t - raw[0].t) : 1 / 30;

  const closeIfMissing = (id: number, fi: number) => {
    const o = open.get(id);
    if (!o) return;
    let arr = out.get(id);
    if (!arr) { arr = []; out.set(id, arr); }
    arr.push({ start: o.start, end: o.lastT + dt / 2 });
    open.delete(id);
    void fi;
  };

  for (let fi = 0; fi < raw.length; fi++) {
    const t = raw[fi].t;
    const present = perFrame[fi];

    // Open new / extend existing
    for (const id of present.keys()) {
      const o = open.get(id);
      if (o) {
        o.lastT = t;
      } else {
        open.set(id, { start: t, lastT: t });
      }
    }

    // Close any IDs that were open but missing this frame
    for (const id of Array.from(open.keys())) {
      if (!present.has(id)) closeIfMissing(id, fi);
    }
  }

  // Final flush
  for (const id of Array.from(open.keys())) {
    closeIfMissing(id, raw.length);
  }

  // Merge tiny gaps + drop blip segments per ID.
  for (const [id, segs] of out) {
    segs.sort((a, b) => a.start - b.start);

    // Merge gaps shorter than PRESENCE_GAP_MERGE
    const merged: PresenceSegment[] = [];
    for (const s of segs) {
      const last = merged[merged.length - 1];
      if (last && s.start - last.end <= PRESENCE_GAP_MERGE) {
        last.end = Math.max(last.end, s.end);
      } else {
        merged.push({ ...s });
      }
    }

    // Drop segments shorter than the minimum
    const filtered = merged.filter((s) => s.end - s.start >= PRESENCE_MIN_SEGMENT);

    if (filtered.length === 0) {
      out.delete(id);
    } else {
      out.set(id, filtered);
    }
  }

  return out;
}

/**
 * Build a `PresenceTrack` from raw multi-person detections. Independent of
 * the single-person `PoseTrack` used for rendering.
 */
export function derivePresenceTrack(raw: RawFrame[]): PresenceTrack {
  if (raw.length === 0) return [];

  const perFrame = trackIdentities(raw);
  const segMap = buildSegments(raw, perFrame);

  // Stable order: by first appearance (smaller original ID = earlier).
  const ids = Array.from(segMap.keys()).sort((a, b) => a - b);

  // Re-number to a dense [0, N) range so colors don't skip in the UI when
  // some intermediate IDs were filtered out as blips.
  return ids.map((origId, i) => ({
    id: i,
    color: PERSON_COLORS[i % PERSON_COLORS.length],
    segments: segMap.get(origId)!,
  }));
}

/** Returns the sorted list of person IDs visible at time `t`. */
export function presenceAtTime(track: PresenceTrack, t: number): number[] {
  const out: number[] = [];
  for (const p of track) {
    // Linear scan is fine — segments per person is small (tens, not millions).
    for (const s of p.segments) {
      if (s.start > t) break;
      if (s.end >= t) { out.push(p.id); break; }
    }
  }
  return out;
}

// ── Body Text — Vision Service (Pose Tracking) ──────────────────────────────
//
// MediaPipe Pose Landmarker wrapper.
//
// Optimizations applied:
//   • Warm-up frame after init   → removes first-real-frame JIT stutter
//   • IMAGE-mode priming         → flushes stale temporal state on export
//   • Tuned confidence           → fewer redundant re-detections once locked
//   • numPoses: 3, full model    → per user preference
//   • GPU delegate               → enabled for accelerated performance

import { FilesetResolver, PoseLandmarker } from '@mediapipe/tasks-vision';
import {
  AnalysisProgress,
  PoseFrame,
  PoseTrack,
  PresenceTrack,
  TrackedLandmark,
} from '../types';
import {
  buildFrames,
  derivePresenceTrack,
  fillGaps,
  outlierReject,
  smoothBidirectional,
  RawFrame,
} from './poseTrack';

export interface PoseResult {
  /** Array of detected poses; each contains 33 normalized landmarks */
  landmarks: Array<Array<{ x: number; y: number; z: number; visibility?: number }>>;
}

class VisionService {
  private poseLandmarker: PoseLandmarker | null = null;
  private isInitializing = false;
  private lastTimestamp = -1;

  async initialize() {
    if (this.poseLandmarker) return;
    if (this.isInitializing) return;

    this.isInitializing = true;
    try {
      const vision = await FilesetResolver.forVisionTasks(
        'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision/wasm'
      );

      this.poseLandmarker = await PoseLandmarker.createFromOptions(vision, {
        baseOptions: {
          modelAssetPath:
            'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/1/pose_landmarker_full.task',
          delegate: 'GPU',
        },
        // Tuned: detection slightly stricter, tracking slightly looser →
        // detector spends less effort re-acquiring once it has a lock.
        minPoseDetectionConfidence: 0.6,
        minPosePresenceConfidence: 0.5,
        minTrackingConfidence: 0.4,
        runningMode: 'VIDEO',
        numPoses: 3,
      });

      // Warm-up frame: compile the graph on a 1×1 canvas so the first
      // real frame doesn't pay JIT cost.
      try {
        const warm = document.createElement('canvas');
        warm.width = 1;
        warm.height = 1;
        this.poseLandmarker.detectForVideo(warm, 0);
        this.lastTimestamp = 0;
      } catch {
        /* non-fatal; continue */
      }
    } catch (error) {
      console.error('Failed to initialize Pose Landmarker:', error);
      throw error;
    } finally {
      this.isInitializing = false;
    }
  }

  /** Real-time processing with temporal smoothing (VIDEO mode). */
  detectPoses(video: HTMLVideoElement, timestampMs: number): PoseResult {
    if (!this.poseLandmarker) return { landmarks: [] };

    // MediaPipe requires strictly increasing timestamps.
    if (timestampMs <= this.lastTimestamp) {
      timestampMs = this.lastTimestamp + 1;
    }
    this.lastTimestamp = timestampMs;

    try {
      const result = this.poseLandmarker.detectForVideo(video, timestampMs);
      return this.processLandmarks(result.landmarks || []);
    } catch {
      return { landmarks: [] };
    }
  }

  /** Switch to IMAGE mode for offline per-frame export. Primes to flush state. */
  async prepareForExport() {
    if (!this.poseLandmarker) return;
    await this.poseLandmarker.setOptions({ runningMode: 'IMAGE' });
    // Priming call — flushes any lingering temporal state from VIDEO mode.
    try {
      const blank = document.createElement('canvas');
      blank.width = 1;
      blank.height = 1;
      this.poseLandmarker.detect(blank);
    } catch {
      /* non-fatal */
    }
  }

  /** Restore VIDEO mode after export. */
  async restoreAfterExport() {
    if (!this.poseLandmarker) return;
    await this.poseLandmarker.setOptions({ runningMode: 'VIDEO' });
    this.lastTimestamp = -1;
  }

  /** Offline frame-by-frame detection (requires IMAGE runningMode). */
  detectInFrame(image: HTMLCanvasElement | HTMLImageElement | HTMLVideoElement): PoseResult {
    if (!this.poseLandmarker) return { landmarks: [] };
    try {
      const result = this.poseLandmarker.detect(image);
      return this.processLandmarks(result.landmarks || []);
    } catch (err) {
      console.warn('detectInFrame failed:', err);
      return { landmarks: [] };
    }
  }

  private processLandmarks(landmarks: any[]): PoseResult {
    // Sort poses by horizontal position (leftmost → index 0) for stable
    // person-picker UX across frames. Uses shoulder midpoint as reference.
    if (landmarks.length > 1) {
      landmarks.sort((a, b) => {
        const ax = ((a[11]?.x ?? 0.5) + (a[12]?.x ?? 0.5)) / 2;
        const bx = ((b[11]?.x ?? 0.5) + (b[12]?.x ?? 0.5)) / 2;
        return ax - bx;
      });
    }
    return { landmarks };
  }

  /** Reset timestamp tracking (call when switching sources or starting export). */
  resetTimestamp() {
    this.lastTimestamp = -1;
  }

  /**
   * Pre-pass analysis for uploaded videos.
   *
   * Steps through every decoded frame via requestVideoFrameCallback (falling
   * back to a seek loop if unavailable) and runs IMAGE-mode detection.
   *
   * Produces TWO outputs from the same raw pass:
   *   • track    — single-person PoseTrack (highest-visibility per frame,
   *                smoothed/gap-filled) used by the renderer for anchoring.
   *   • presence — multi-person PresenceTrack used by the timeline strip.
   *
   * Emits only coarse status ('analyzing' | 'done' | 'error'). Abortable.
   */
  async analyzeVideo(
    video: HTMLVideoElement,
    onStatus: (p: AnalysisProgress) => void,
    signal?: AbortSignal,
  ): Promise<{ track: PoseTrack; presence: PresenceTrack }> {
    await this.initialize();
    if (!this.poseLandmarker) return { track: [], presence: [] };

    // Remember & restore user-visible state
    const wasPaused = video.paused;
    const originalTime = video.currentTime;
    const originalMuted = video.muted;
    const originalRate = video.playbackRate;
    const originalLoop = video.loop;

    video.pause();
    video.loop = false;
    video.muted = true;
    video.currentTime = 0;

    // Wait for seek to 0 to complete
    await new Promise<void>((resolve) => {
      if (Math.abs(video.currentTime) < 0.001 && video.readyState >= 2) {
        resolve();
        return;
      }
      const handler = () => {
        video.removeEventListener('seeked', handler);
        resolve();
      };
      video.addEventListener('seeked', handler);
    });

    await this.poseLandmarker.setOptions({ runningMode: 'IMAGE' });

    const raw: RawFrame[] = [];

    onStatus({ status: 'analyzing' });

    const hasRVFC = 'requestVideoFrameCallback' in HTMLVideoElement.prototype;

    try {
      if (hasRVFC) {
        await this.analyzeViaPlayback(video, raw, signal);
      } else {
        await this.analyzeViaSeek(video, raw, signal);
      }
    } finally {
      // Restore playback state regardless of success
      await this.poseLandmarker.setOptions({ runningMode: 'VIDEO' });
      this.lastTimestamp = -1;
      video.playbackRate = originalRate;
      video.muted = originalMuted;
      video.loop = originalLoop;
      try { video.currentTime = originalTime; } catch { /* noop */ }
      if (!wasPaused) {
        try { await video.play(); } catch { /* noop */ }
      } else {
        video.pause();
      }
    }

    if (signal?.aborted) return { track: [], presence: [] };

    // ── Post-processing ──────────────────────────────────────────────
    // Single-person track for the renderer.
    let track: PoseFrame[] = buildFrames(raw);
    track = outlierReject(track);
    track = fillGaps(track);
    track = smoothBidirectional(track);

    // Multi-person presence track for the timeline strip. Built from the
    // SAME raw frames so we don't pay the analyzer cost twice.
    const presence = derivePresenceTrack(raw);

    onStatus({ status: 'done' });
    return { track, presence };
  }

  // ── Analysis strategy: play at high rate, sample every decoded frame ─────
  private async analyzeViaPlayback(
    video: HTMLVideoElement,
    raw: RawFrame[],
    signal?: AbortSignal,
  ): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      if (!this.poseLandmarker) {
        resolve();
        return;
      }
      const vid = video as any;
      let handle: number | undefined;
      let done = false;

      const cleanup = () => {
        if (handle !== undefined && 'cancelVideoFrameCallback' in video) {
          try { vid.cancelVideoFrameCallback(handle); } catch { /* noop */ }
        }
        video.onended = null;
        video.onpause = null;
      };

      const finish = () => {
        if (done) return;
        done = true;
        cleanup();
        resolve();
      };

      const onFrame = (_now: number, meta: { mediaTime: number }) => {
        if (done) return;
        if (signal?.aborted) { finish(); return; }
        try {
          const detect = this.poseLandmarker!.detect(video);
          const poses = (detect.landmarks || []).map((lms: any[]) => ({
            landmarks: lms.map(
              (lm): TrackedLandmark => ({
                x: lm.x,
                y: lm.y,
                z: lm.z ?? 0,
                visibility: lm.visibility ?? 1,
              }),
            ),
          }));
          raw.push({ t: meta.mediaTime, poses });
        } catch {
          raw.push({ t: meta.mediaTime, poses: [] });
        }
        handle = vid.requestVideoFrameCallback(onFrame);
      };

      video.onended = () => finish();
      video.onpause = () => {
        // Only treat as done if we actually reached the end
        if (video.currentTime >= video.duration - 0.05) finish();
      };
      signal?.addEventListener('abort', finish);

      // Play muted at 2x (still captures every decoded frame via rVFC, but
      // gets through the video faster). Some browsers clamp this internally.
      video.muted = true;
      video.playbackRate = 2;
      handle = vid.requestVideoFrameCallback(onFrame);
      video.play().catch((e) => {
        cleanup();
        reject(e);
      });
    });
  }

  // ── Fallback: seek-and-wait loop at ~30fps ───────────────────────────────
  private async analyzeViaSeek(
    video: HTMLVideoElement,
    raw: RawFrame[],
    signal?: AbortSignal,
  ): Promise<void> {
    if (!this.poseLandmarker) return;
    const duration = video.duration;
    const step = 1 / 30;

    for (let t = 0; t < duration; t += step) {
      if (signal?.aborted) return;
      video.currentTime = t;
      await new Promise<void>((resolve) => {
        const handler = () => {
          video.removeEventListener('seeked', handler);
          resolve();
        };
        video.addEventListener('seeked', handler);
      });
      try {
        const detect = this.poseLandmarker.detect(video);
        const poses = (detect.landmarks || []).map((lms: any[]) => ({
          landmarks: lms.map(
            (lm): TrackedLandmark => ({
              x: lm.x,
              y: lm.y,
              z: lm.z ?? 0,
              visibility: lm.visibility ?? 1,
            }),
          ),
        }));
        raw.push({ t: video.currentTime, poses });
      } catch {
        raw.push({ t: video.currentTime, poses: [] });
      }
    }
  }

  isReady(): boolean {
    return this.poseLandmarker !== null;
  }
}

export const visionService = new VisionService();

