import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Loader2 } from 'lucide-react';
import { Flow } from 'flow-sdk';
import { BodyText, PoseTrack, PresenceTrack, AnalysisProgress } from './types';
import { DEFAULT_BODY_TEXT, DEFAULT_TEXT_DURATION, MIN_TEXT_DURATION } from './constants';
import { PoseResult } from './services/visionService';
import { VideoStage, VideoStageHandle } from './components/CameraView';
import { RightPanel } from './components/RightPanel';
import { Timeline } from './components/Timeline';
import { StartScreen } from './components/StartScreen';
import { Onboarding } from './components/Onboarding';
import { visionService } from './services/visionService';

let textIdCounter = 0;
function nextTextId() {
  return `bt-${++textIdCounter}-${Date.now()}`;
}

export default function App() {
  // ── State ───────────────────────────────────────────────────────────────
  const [started, setStarted] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isModelLoading, setIsModelLoading] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showLandmarks, setShowLandmarks] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [texts, setTexts] = useState<BodyText[]>([]);
  const [editingTextId, setEditingTextId] = useState<string | null>(null);
  const [poseCount, setPoseCount] = useState(0);

  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [exportProgress, setExportProgress] = useState(0);
  const [isExportActive, setIsExportActive] = useState(false);

  // Pre-pass pose tracking
  const [poseTrack, setPoseTrack] = useState<PoseTrack | null>(null);
  const [presence, setPresence] = useState<PresenceTrack | null>(null);
  const [analysisProgress, setAnalysisProgress] = useState<AnalysisProgress | null>(null);
  const [hasSeenOnboarding, setHasSeenOnboarding] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);

  const analysisAbortRef = useRef<AbortController | null>(null);
  const stageRef = useRef<VideoStageHandle>(null);

  // ── Handlers ────────────────────────────────────────────────────────────
  const handlePoseUpdate = useCallback((result: PoseResult) => {
    setPoseCount(result.landmarks.length);
  }, []);

  const handleAddText = useCallback(() => {
    let startTime = 0;
    let endTime = 0;
    if (duration > 0) {
      startTime = Math.max(0, Math.min(currentTime, duration - MIN_TEXT_DURATION));
      endTime = Math.min(startTime + DEFAULT_TEXT_DURATION, duration);
      if (endTime - startTime < MIN_TEXT_DURATION) {
        endTime = Math.min(startTime + MIN_TEXT_DURATION, duration);
      }
    }
    const newText: BodyText = {
      id: nextTextId(),
      ...DEFAULT_BODY_TEXT,
      startTime,
      endTime,
    };
    setTexts((prev) => [...prev, newText]);
    setEditingTextId(newText.id);
  }, [duration, currentTime]);

  const handleUpdateText = useCallback((updated: BodyText) => {
    setTexts((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
  }, []);

  const handleDeleteText = useCallback((id: string) => {
    setTexts((prev) => prev.filter((t) => t.id !== id));
    setEditingTextId(null);
  }, []);

  const handleExport = useCallback(async () => {
    if (stageRef.current) {
      setIsExportActive(true);
      try {
        await stageRef.current.exportVideo();
      } finally {
        setIsExportActive(false);
      }
    }
  }, []);

  const abortAnalysis = useCallback(() => {
    if (analysisAbortRef.current) {
      analysisAbortRef.current.abort();
      analysisAbortRef.current = null;
    }
  }, []);

  const handleLoadVideo = useCallback(async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (!media) return;

      abortAnalysis();
      setPoseTrack(null);
      setPresence(null);
      setAnalysisProgress(null);
      setShowOnboarding(false);

      const bytes = Uint8Array.from(atob(media.base64), (c) => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: media.mimeType });
      setVideoUrl(URL.createObjectURL(blob));

      setIsPlaying(false);
      setCurrentTime(0);
      setStarted(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Video selection failed');
    }
  }, [abortAnalysis]);

  const handleSeek = useCallback((time: number) => {
    setCurrentTime(time);
    stageRef.current?.seekTo(time);
  }, []);

  const handleTogglePlay = useCallback(() => {
    if (analysisProgress && analysisProgress.status === 'analyzing') return;
    setIsPlaying((p) => !p);
  }, [analysisProgress]);

  const runAnalysis = useCallback(async () => {
    const videoEl = stageRef.current?.getVideoElement();
    if (!videoEl) return;

    abortAnalysis();
    const controller = new AbortController();
    analysisAbortRef.current = controller;

    setPoseTrack(null);
    setPresence(null);
    setAnalysisProgress({ status: 'analyzing' });

    try {
      const result = await visionService.analyzeVideo(
        videoEl,
        (p) => {
          if (controller.signal.aborted) return;
          setAnalysisProgress(p);
        },
        controller.signal,
      );

      if (controller.signal.aborted) return;
      setPoseTrack(result.track);
      setPresence(result.presence);
      setAnalysisProgress({ status: 'done' });

      // Trigger onboarding if it's the first time
      if (!hasSeenOnboarding) {
        setShowOnboarding(true);
      }
    } catch (err) {
      if (controller.signal.aborted) return;
      setError(err instanceof Error ? err.message : 'Video analysis failed');
      setAnalysisProgress({ status: 'error' });
    } finally {
      if (analysisAbortRef.current === controller) {
        analysisAbortRef.current = null;
      }
    }
  }, [abortAnalysis, hasSeenOnboarding]);

  const handleCancelAnalysis = useCallback(() => {
    abortAnalysis();
    setAnalysisProgress(null);
    setPoseTrack(null);
    setPresence(null);
    setVideoUrl(null);
    setIsPlaying(false);
    setCurrentTime(0);
    setDuration(0);
    setShowOnboarding(false);
  }, [abortAnalysis]);

  const handleVideoReady = useCallback((dur: number) => {
    setDuration(dur);
    runAnalysis();
  }, [runAnalysis]);

  const handleStartVideo = useCallback(async () => {
    await handleLoadVideo();
  }, [handleLoadVideo]);

  const handleOnboardingComplete = () => {
    setShowOnboarding(false);
    setHasSeenOnboarding(true);
  };

  useEffect(() => () => { abortAnalysis(); }, [abortAnalysis]);

  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      .scrollbar-hide::-webkit-scrollbar { display: none; }
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      input[type=range]::-moz-range-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-moz-range-thumb { width: 14px; height: 14px; border: none; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); cursor: grab; }
      input[type=range]::-moz-range-thumb:active { cursor: grabbing; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to   { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
    `;
    document.head.appendChild(style);
    return () => { style.remove(); };
  }, []);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
      if (e.code === 'Space') {
        e.preventDefault();
        if (analysisProgress?.status === 'analyzing') return;
        setIsPlaying((p) => !p);
        return;
      }
      if ((e.key === '[' || e.key === ']') && editingTextId) {
        e.preventDefault();
        setTexts((prev) => prev.map((t) => {
          if (t.id !== editingTextId) return t;
          if (e.key === '[') {
            const start = Math.max(0, Math.min(currentTime, t.endTime - MIN_TEXT_DURATION));
            return { ...t, startTime: start };
          } else {
            const end = Math.min(duration, Math.max(currentTime, t.startTime + MIN_TEXT_DURATION));
            return { ...t, endTime: end };
          }
        }));
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [analysisProgress, editingTextId, currentTime, duration]);

  if (!started) {
    return <StartScreen onUploadVideo={handleStartVideo} />;
  }

  const isExporting = exportProgress > 0 && exportProgress < 1;
  const isAnalyzing = analysisProgress?.status === 'analyzing';
  const hasVideo = videoUrl !== null;

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e]">
      <div className="flex-1 relative min-w-0">
        <VideoStage
          ref={stageRef}
          videoUrl={videoUrl}
          texts={texts}
          poseTrack={poseTrack}
          onLoadingChange={setIsModelLoading}
          onError={setError}
          onPoseUpdate={handlePoseUpdate}
          showLandmarks={showLandmarks}
          isPlaying={isPlaying && !isAnalyzing}
          onTimeUpdate={(cur, dur) => { setCurrentTime(cur); setDuration(dur); }}
          onVideoReady={handleVideoReady}
          onExportProgress={setExportProgress}
        />

        {hasVideo && !isAnalyzing && duration > 0 && (
          <Timeline
            texts={texts}
            currentTime={currentTime}
            duration={duration}
            isPlaying={isPlaying}
            selectedTextId={editingTextId}
            presence={presence}
            onTogglePlay={handleTogglePlay}
            onSeek={handleSeek}
            onSelectText={setEditingTextId}
            onUpdateTexts={setTexts}
          />
        )}

        {showOnboarding && <Onboarding onComplete={handleOnboardingComplete} />}

        {!hasVideo && !isModelLoading && (
          <div className="absolute inset-0 flex flex-col items-center justify-center z-20 pointer-events-none">
            <div className="flex flex-col items-center gap-3 pointer-events-auto">
              <span className="text-3xl">🎬</span>
              <p className="text-[12px] font-medium text-[rgba(218,220,224,0.75)] tracking-[0.1px]">
                No video loaded
              </p>
              <button
                onClick={handleLoadVideo}
                className="px-4 h-[34px] rounded-xl bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer"
              >
                Upload Video
              </button>
            </div>
          </div>
        )}

        {isAnalyzing && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#0e0e0e] z-30">
            <Loader2 className="w-8 h-8 animate-spin text-white mb-3" strokeWidth={1.5} />
            <p className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
              Analyzing video…
            </p>
            <button
              onClick={handleCancelAnalysis}
              className="mt-4 px-3 py-1.5 text-[11px] font-medium text-white/80 hover:text-white border border-[rgba(218,220,224,0.15)] hover:border-[rgba(218,220,224,0.3)] rounded-xl transition-colors cursor-pointer"
            >
              Cancel
            </button>
          </div>
        )}

        {(isModelLoading && !isExporting) && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm z-50">
            <Loader2 className="w-8 h-8 animate-spin text-white mb-3" />
            <p className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] animate-pulse">
              {isExportActive ? 'Exporting...' : 'Initializing...'}
            </p>
          </div>
        )}

        {isExporting && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-md z-50">
            <div className="w-64 flex flex-col items-center gap-4">
              <div className="relative w-16 h-16">
                 <svg className="w-full h-full" viewBox="0 0 100 100">
                    <circle cx="50" cy="50" r="45" fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth="8" />
                    <circle cx="50" cy="50" r="45" fill="none" stroke="white" strokeWidth="8" strokeLinecap="round"
                      strokeDasharray={`${exportProgress * 283} 283`} transform="rotate(-90 50 50)" />
                 </svg>
                 <span className="absolute inset-0 flex items-center justify-center text-[11px] font-bold text-white">
                   {Math.round(exportProgress * 100)}%
                 </span>
              </div>
              <p className="text-[12px] font-medium text-white tracking-[0.1px]">Exporting High-Quality Video...</p>
              <p className="text-[10px] text-[rgba(255,255,255,0.4)] text-center max-w-xs">
                Rendering every frame for maximum tracking precision. This may take a moment.
              </p>
            </div>
          </div>
        )}

        {error && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 px-4 py-2.5 border border-red-500/30 rounded-2xl text-[11px] font-medium text-red-300 tracking-[0.1px] z-50" style={{ background: 'rgba(26,26,26,0.9)', backdropFilter: 'blur(20px)' }}>
            {error}
            <button onClick={() => setError(null)} className="ml-3 underline cursor-pointer">Dismiss</button>
          </div>
        )}
      </div>

      <RightPanel
        showLandmarks={showLandmarks}
        texts={texts}
        editingTextId={editingTextId}
        poseCount={poseCount}
        onLoadVideo={handleLoadVideo}
        onToggleLandmarks={() => setShowLandmarks((s) => !s)}
        onAddText={handleAddText}
        onExport={handleExport}
        onSelectText={setEditingTextId}
        onUpdateText={handleUpdateText}
        onDeleteText={handleDeleteText}
      />
    </div>
  );
}

// ── Body Text — Onboarding (Feature Tour) ───────────────────────────────────

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { Sparkles, MousePointer2, Layout, CheckCircle2 } from 'lucide-react';

interface OnboardingStep {
  title: string;
  description: string;
  icon: React.ReactNode;
  position: 'bottom' | 'right' | 'center';
  targetLabel: string;
}

interface OnboardingProps {
  onComplete: () => void;
}

const STEPS: OnboardingStep[] = [
  {
    title: "Analysis Complete",
    description: "We've mapped your character's skeleton across the entire video. You're ready to start tagging.",
    icon: <Sparkles className="text-blue-400" size={20} />,
    position: 'center',
    targetLabel: "Welcome"
  },
  {
    title: "The Presence Map",
    description: "These colored blocks on the timeline show exactly when landmarks were detected. Use them to time your labels perfectly.",
    icon: <Layout className="text-purple-400" size={20} />,
    position: 'bottom',
    targetLabel: "Timeline"
  },
  {
    title: "Drag to Adjust",
    description: "Add a text label, then drag its edges on the timeline to control its appearance. It will stay locked to the body as it moves.",
    icon: <MousePointer2 className="text-green-400" size={20} />,
    position: 'right',
    targetLabel: "Controls"
  }
];

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const step = STEPS[currentStep];

  const handleNext = () => {
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(v => v + 1);
    } else {
      onComplete();
    }
  };

  // Auto-dismiss or escape key
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onComplete();
      if (e.key === 'Enter') handleNext();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [currentStep]);

  return (
    <div className="fixed inset-0 z-[100] pointer-events-none">
      {/* Dimmer backdrop */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="absolute inset-0 bg-black/40 backdrop-blur-[2px] pointer-events-auto"
        onClick={onComplete}
      />

      <AnimatePresence mode="wait">
        <motion.div
          key={currentStep}
          initial={{ opacity: 0, y: 10, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: -10, scale: 0.95 }}
          transition={{ duration: 0.2, ease: "easeOut" }}
          className={`absolute pointer-events-auto w-[300px] border border-[#595959] rounded-2xl p-5 shadow-2xl bg-[#1a1a1a] flex flex-col gap-4
            ${step.position === 'center' ? 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2' : ''}
            ${step.position === 'bottom' ? 'bottom-32 left-1/2 -translate-x-1/2' : ''}
            ${step.position === 'right' ? 'right-[320px] bottom-12' : ''}
          `}
        >
          {/* Progress dots */}
          <div className="flex gap-1">
            {STEPS.map((_, i) => (
              <div 
                key={i} 
                className={`h-1 rounded-full transition-all duration-300 ${i === currentStep ? 'w-4 bg-white' : 'w-1 bg-white/20'}`} 
              />
            ))}
          </div>

          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center shrink-0">
              {step.icon}
            </div>
            <h2 className="text-[14px] font-bold text-white tracking-tight leading-tight">
              {step.title}
            </h2>
          </div>

          <p className="text-[12px] font-medium text-[rgba(218,220,224,0.7)] leading-relaxed">
            {step.description}
          </p>

          <div className="flex items-center justify-between pt-2">
            <button 
              onClick={onComplete}
              className="text-[11px] font-medium text-[rgba(218,220,224,0.4)] hover:text-white transition-colors"
            >
              Skip tour
            </button>
            <button
              onClick={handleNext}
              className="h-8 px-4 rounded-lg bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[11px] font-bold tracking-[0.1px] transition-all flex items-center gap-1.5"
            >
              <span>{currentStep === STEPS.length - 1 ? 'Get Started' : 'Next'}</span>
              {currentStep === STEPS.length - 1 ? <CheckCircle2 size={12} strokeWidth={2.5} /> : null}
            </button>
          </div>

          {/* Arrow pointer for specific contexts */}
          {step.position === 'bottom' && (
            <div className="absolute left-1/2 -translate-x-1/2 top-full w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent border-t-[8px] border-t-[#595959]" />
          )}
          {step.position === 'right' && (
            <div className="absolute left-full top-1/2 -translate-y-1/2 w-0 h-0 border-t-[8px] border-t-transparent border-b-[8px] border-b-transparent border-l-[8px] border-l-[#595959]" />
          )}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};
